/**
 * RealWorld 스펙의 에러 응답 형식을 표현한다.
 * 본문은 항상 `{ "errors": { "필드": ["메시지", ...] } }` 모양이다.
 */
export type ErrorBody = Record<string, string[]>;

export class ApiError extends Error {
  readonly statusCode: number;
  readonly errors: ErrorBody;

  constructor(statusCode: number, errors: ErrorBody) {
    super(`API 오류 (${statusCode})`);
    this.statusCode = statusCode;
    this.errors = errors;
  }
}

/** 422 — 입력 검증 실패 */
export const unprocessable = (errors: ErrorBody) => new ApiError(422, errors);

/** 401 — 토큰 누락 */
export const missingToken = () => new ApiError(401, { token: ["is missing"] });

/** 401 — 토큰이 유효하지 않음 */
export const invalidToken = () => new ApiError(401, { token: ["is invalid"] });

/** 401 — 로그인 자격 증명 불일치 */
export const invalidCredentials = () =>
  new ApiError(401, { credentials: ["invalid"] });

/** 404 — 리소스 없음 */
export const notFound = (resource: string) =>
  new ApiError(404, { [resource]: ["not found"] });

/** 403 — 소유자가 아니라 권한 없음 */
export const forbidden = (resource: string) =>
  new ApiError(403, { [resource]: ["forbidden"] });

/** 409 — 유일성 제약 위반 */
export const alreadyTaken = (field: string) =>
  new ApiError(409, { [field]: ["has already been taken"] });

