import { createHmac, timingSafeEqual } from "node:crypto";

/**
 * 의존성 없는 최소 HS256 JWT 구현.
 * 페이로드에는 사용자 id만 담아, 이후 username/email이 바뀌어도 토큰이 유효하게 유지한다.
 */

const SECRET = process.env.JWT_SECRET ?? "realworld-dev-secret";
/** 토큰 유효 기간(초) — 기본 30일 */
const TTL_SECONDS = Number(process.env.JWT_TTL_SECONDS ?? 60 * 60 * 24 * 30);

const base64url = (input: Buffer | string): string =>
  Buffer.from(input)
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");

const fromBase64url = (input: string): Buffer =>
  Buffer.from(input.replace(/-/g, "+").replace(/_/g, "/"), "base64");

const sign = (data: string): string =>
  base64url(createHmac("sha256", SECRET).update(data).digest());

export interface TokenPayload {
  /** 사용자 id */
  sub: number;
  /** 발급 시각 (초) */
  iat: number;
  /** 만료 시각 (초) */
  exp: number;
}

export function signToken(userId: number): string {
  const now = Math.floor(Date.now() / 1000);
  const header = base64url(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const payload = base64url(
    JSON.stringify({ sub: userId, iat: now, exp: now + TTL_SECONDS }),
  );
  const data = `${header}.${payload}`;
  return `${data}.${sign(data)}`;
}

/** 검증에 실패하면 null을 돌려준다. */
export function verifyToken(token: string): TokenPayload | null {
  const parts = token.split(".");
  if (parts.length !== 3) return null;

  const [header, payload, signature] = parts;
  const expected = sign(`${header}.${payload}`);
  const given = Buffer.from(signature);
  const want = Buffer.from(expected);
  if (given.length !== want.length || !timingSafeEqual(given, want)) return null;

  try {
    const decoded = JSON.parse(fromBase64url(payload).toString("utf8"));
    if (typeof decoded?.sub !== "number") return null;
    if (typeof decoded?.exp === "number" && decoded.exp < Date.now() / 1000) {
      return null;
    }
    return decoded as TokenPayload;
  } catch {
    return null;
  }
}

