import { unprocessable, type ErrorBody } from "./errors.js";

/** NIST 800-63B 권고에 따른 최소 비밀번호 길이 */
export const MIN_PASSWORD_LENGTH = 8;

/** 여러 필드의 검증 오류를 모았다가 한 번에 422로 던지는 수집기 */
export class Validator {
  private readonly errors: ErrorBody = {};

  add(field: string, message: string): void {
    (this.errors[field] ??= []).push(message);
  }

  get hasErrors(): boolean {
    return Object.keys(this.errors).length > 0;
  }

  /** 오류가 하나라도 있으면 422 예외를 던진다. */
  throwIfInvalid(): void {
    if (this.hasErrors) throw unprocessable(this.errors);
  }
}

/** 요청 본문이 객체인지 확인하고, 아니면 빈 객체로 취급한다. */
export function asRecord(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

/**
 * 필수 문자열 필드를 검증한다.
 * 값이 없거나 공백뿐이면 "can't be blank"를 기록하고 undefined를 돌려준다.
 */
export function requireString(
  v: Validator,
  input: Record<string, unknown>,
  field: string,
): string | undefined {
  const value = input[field];
  if (typeof value === "string" && value.trim() !== "") return value;
  v.add(field, "can't be blank");
  return undefined;
}

/**
 * 선택적 문자열 필드를 검증한다. 키 자체가 없으면 undefined(변경 없음)를 돌려준다.
 * 값이 있는데 비었거나 문자열이 아니면 "can't be blank"를 기록한다.
 */
export function optionalRequiredString(
  v: Validator,
  input: Record<string, unknown>,
  field: string,
): string | undefined {
  if (!(field in input)) return undefined;
  return requireString(v, input, field);
}

/**
 * bio/image처럼 null을 허용하는 필드를 정규화한다.
 * 빈 문자열은 null로 바꾸고, 키가 없으면 undefined(변경 없음)를 돌려준다.
 */
export function nullableString(
  v: Validator,
  input: Record<string, unknown>,
  field: string,
): string | null | undefined {
  if (!(field in input)) return undefined;
  const value = input[field];
  if (value === null) return null;
  if (typeof value !== "string") {
    v.add(field, "is invalid");
    return undefined;
  }
  return value.trim() === "" ? null : value;
}

/** 비밀번호 정책 검증. 키가 없으면 undefined(변경 없음). */
export function passwordField(
  v: Validator,
  input: Record<string, unknown>,
  field = "password",
): string | undefined {
  if (!(field in input)) return undefined;
  const value = input[field];
  if (typeof value !== "string" || value.trim() === "") {
    v.add(field, "can't be blank");
    return undefined;
  }
  if (value.length < MIN_PASSWORD_LENGTH) {
    v.add(field, `is too short (minimum is ${MIN_PASSWORD_LENGTH} characters)`);
    return undefined;
  }
  return value;
}

/** tagList 검증. 키가 없으면 undefined(기존 태그 유지), null이면 422. */
export function tagListField(
  v: Validator,
  input: Record<string, unknown>,
): string[] | undefined {
  if (!("tagList" in input)) return undefined;
  const value = input.tagList;
  if (!Array.isArray(value) || value.some((t) => typeof t !== "string")) {
    v.add("tagList", "is invalid");
    return undefined;
  }
  // 공백 제거 후 중복을 걷어낸다.
  const cleaned = (value as string[]).map((t) => t.trim()).filter(Boolean);
  return [...new Set(cleaned)];
}

/** limit/offset 쿼리 파라미터를 안전한 정수로 변환한다. */
export function parsePagination(query: Record<string, unknown>): {
  limit: number;
  offset: number;
} {
  const toInt = (raw: unknown, fallback: number, min: number): number => {
    const n = Number.parseInt(String(raw ?? ""), 10);
    return Number.isFinite(n) && n >= min ? n : fallback;
  };
  return {
    limit: Math.min(toInt(query.limit, 20, 0), 500),
    offset: toInt(query.offset, 0, 0),
  };
}

