import type { Article, Comment, Tag, User } from "@prisma/client";
import { signToken } from "./jwt.js";

/** ISO 8601(밀리초 포함) 문자열로 직렬화한다. */
const iso = (date: Date): string => date.toISOString();

export interface ProfileView {
  username: string;
  bio: string | null;
  image: string | null;
  following: boolean;
}

export function toUserView(user: User) {
  return {
    email: user.email,
    token: signToken(user.id),
    username: user.username,
    bio: user.bio,
    image: user.image,
  };
}

export function toProfileView(user: User, following: boolean): ProfileView {
  return {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  };
}

/** 프레젠테이션에 필요한 연관 데이터를 함께 실은 아티클 */
export type ArticleWithRelations = Article & {
  author: User;
  tags: Tag[];
};

export interface ArticleViewOptions {
  favorited: boolean;
  favoritesCount: number;
  following: boolean;
  /** 목록 응답에서는 body를 제외한다. */
  includeBody?: boolean;
}

export function toArticleView(
  article: ArticleWithRelations,
  opts: ArticleViewOptions,
) {
  const view: Record<string, unknown> = {
    slug: article.slug,
    title: article.title,
    description: article.description,
  };
  if (opts.includeBody !== false) view.body = article.body;

  // 태그는 결정적인 순서를 위해 사전순으로 정렬한다.
  view.tagList = article.tags.map((t) => t.name).sort();
  view.createdAt = iso(article.createdAt);
  view.updatedAt = iso(article.updatedAt);
  view.favorited = opts.favorited;
  view.favoritesCount = opts.favoritesCount;
  view.author = toProfileView(article.author, opts.following);
  return view;
}

export function toCommentView(
  comment: Comment & { author: User },
  following: boolean,
) {
  return {
    id: comment.id,
    createdAt: iso(comment.createdAt),
    updatedAt: iso(comment.updatedAt),
    body: comment.body,
    author: toProfileView(comment.author, following),
  };
}

