import type { FastifyRequest } from "fastify";
import type { User } from "@prisma/client";
import { invalidToken, missingToken } from "./errors.js";
import { verifyToken } from "./jwt.js";
import { prisma } from "./prisma.js";

/** `Authorization: Token <jwt>` (Bearer도 허용) 에서 토큰 문자열을 뽑는다. */
function extractToken(request: FastifyRequest): string | null {
  const header = request.headers.authorization;
  if (!header) return null;
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/**
 * 인증이 선택적인 엔드포인트용. 헤더가 없으면 null.
 * 헤더가 있는데 토큰이 잘못됐으면 401을 던진다.
 */
export async function optionalUser(
  request: FastifyRequest,
): Promise<User | null> {
  const token = extractToken(request);
  if (!token) return null;

  const payload = verifyToken(token);
  if (!payload) throw invalidToken();

  const user = await prisma.user.findUnique({ where: { id: payload.sub } });
  if (!user) throw invalidToken();
  return user;
}

/** 인증이 필수인 엔드포인트용. 헤더가 없으면 401 `token: is missing`. */
export async function requireUser(request: FastifyRequest): Promise<User> {
  if (!extractToken(request)) throw missingToken();
  const user = await optionalUser(request);
  if (!user) throw invalidToken();
  return user;
}

