import type { User } from "@prisma/client";
import { prisma } from "./prisma.js";
import { toArticleView, type ArticleWithRelations } from "./presenters.js";

/** 아티클 조회 시 항상 함께 가져와야 하는 연관 데이터 */
export const articleInclude = { author: true, tags: true } as const;

/**
 * 여러 아티클을 한 번에 뷰로 변환한다.
 * 즐겨찾기 여부·즐겨찾기 수·작성자 팔로우 여부를 배치 조회해 N+1을 피한다.
 */
export async function toArticleViews(
  articles: ArticleWithRelations[],
  currentUser: User | null,
  includeBody: boolean,
): Promise<Record<string, unknown>[]> {
  if (articles.length === 0) return [];

  const articleIds = articles.map((a) => a.id);
  const authorIds = [...new Set(articles.map((a) => a.authorId))];

  const counts = await prisma.favorite.groupBy({
    by: ["articleId"],
    where: { articleId: { in: articleIds } },
    _count: { articleId: true },
  });
  const countByArticle = new Map(
    counts.map((c) => [c.articleId, c._count.articleId]),
  );

  let favoritedIds = new Set<number>();
  let followingIds = new Set<number>();

  if (currentUser) {
    const [favorites, follows] = await Promise.all([
      prisma.favorite.findMany({
        where: { userId: currentUser.id, articleId: { in: articleIds } },
        select: { articleId: true },
      }),
      prisma.follow.findMany({
        where: { followerId: currentUser.id, followingId: { in: authorIds } },
        select: { followingId: true },
      }),
    ]);
    favoritedIds = new Set(favorites.map((f) => f.articleId));
    followingIds = new Set(follows.map((f) => f.followingId));
  }

  return articles.map((article) =>
    toArticleView(article, {
      favorited: favoritedIds.has(article.id),
      favoritesCount: countByArticle.get(article.id) ?? 0,
      following: followingIds.has(article.authorId),
      includeBody,
    }),
  );
}

/** 단일 아티클 뷰 */
export async function toSingleArticleView(
  article: ArticleWithRelations,
  currentUser: User | null,
): Promise<Record<string, unknown>> {
  const [view] = await toArticleViews([article], currentUser, true);
  return view;
}

