import bcrypt from "bcryptjs";
import type { FastifyInstance } from "fastify";
import { optionalUser, requireUser } from "../lib/auth.js";
import { alreadyTaken, invalidCredentials } from "../lib/errors.js";
import { toUserView } from "../lib/presenters.js";
import { prisma } from "../lib/prisma.js";
import {
  Validator,
  asRecord,
  nullableString,
  optionalRequiredString,
  passwordField,
  requireString,
} from "../lib/validation.js";

const BCRYPT_ROUNDS = 10;

/** 인증 및 현재 사용자 관련 라우트 */
export async function userRoutes(app: FastifyInstance): Promise<void> {
  // 회원가입
  app.post("/api/users", async (request, reply) => {
    const input = asRecord(asRecord(request.body).user);
    const v = new Validator();
    const username = requireString(v, input, "username");
    const email = requireString(v, input, "email");
    // 가입 시에는 password 키 자체가 필수다.
    if (!("password" in input)) v.add("password", "can't be blank");
    const password = passwordField(v, input);
    v.throwIfInvalid();

    // 유일성 검사 — 중복은 409로 응답한다.
    const [byUsername, byEmail] = await Promise.all([
      prisma.user.findUnique({ where: { username: username! } }),
      prisma.user.findUnique({ where: { email: email! } }),
    ]);
    if (byUsername) throw alreadyTaken("username");
    if (byEmail) throw alreadyTaken("email");

    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        passwordHash: await bcrypt.hash(password!, BCRYPT_ROUNDS),
      },
    });
    return reply.code(201).send({ user: toUserView(user) });
  });

  // 로그인
  app.post("/api/users/login", async (request, reply) => {
    const input = asRecord(asRecord(request.body).user);
    const v = new Validator();
    const email = requireString(v, input, "email");
    const password = requireString(v, input, "password");
    v.throwIfInvalid();

    const user = await prisma.user.findUnique({ where: { email: email! } });
    if (!user || !(await bcrypt.compare(password!, user.passwordHash))) {
      throw invalidCredentials();
    }
    return reply.send({ user: toUserView(user) });
  });

  // 현재 사용자 조회
  app.get("/api/user", async (request, reply) => {
    const user = await requireUser(request);
    return reply.send({ user: toUserView(user) });
  });

  // 현재 사용자 수정
  app.put("/api/user", async (request, reply) => {
    const current = await requireUser(request);
    const input = asRecord(asRecord(request.body).user);
    const v = new Validator();

    const username = optionalRequiredString(v, input, "username");
    const email = optionalRequiredString(v, input, "email");
    const password = passwordField(v, input);
    const bio = nullableString(v, input, "bio");
    const image = nullableString(v, input, "image");
    v.throwIfInvalid();

    // 다른 사용자가 이미 쓰고 있는 username/email인지 확인한다.
    if (username && username !== current.username) {
      const taken = await prisma.user.findUnique({ where: { username } });
      if (taken) throw alreadyTaken("username");
    }
    if (email && email !== current.email) {
      const taken = await prisma.user.findUnique({ where: { email } });
      if (taken) throw alreadyTaken("email");
    }

    const user = await prisma.user.update({
      where: { id: current.id },
      data: {
        ...(username !== undefined && { username }),
        ...(email !== undefined && { email }),
        ...(bio !== undefined && { bio }),
        ...(image !== undefined && { image }),
        ...(password !== undefined && {
          passwordHash: await bcrypt.hash(password, BCRYPT_ROUNDS),
        }),
      },
    });
    return reply.send({ user: toUserView(user) });
  });

  // 스펙 외 편의 엔드포인트: 서버 상태 확인
  app.get("/api/health", async (request, reply) => {
    await optionalUser(request);
    return reply.send({ status: "ok" });
  });
}

