import type { FastifyInstance } from "fastify";
import type { User } from "@prisma/client";
import { optionalUser, requireUser } from "../lib/auth.js";
import { notFound } from "../lib/errors.js";
import { toProfileView } from "../lib/presenters.js";
import { prisma } from "../lib/prisma.js";

/** username으로 사용자를 찾고, 없으면 404를 던진다. */
async function findProfileOr404(username: string): Promise<User> {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw notFound("profile");
  return user;
}

/** viewer가 target을 팔로우 중인지 확인한다. */
async function isFollowing(
  viewer: User | null,
  target: User,
): Promise<boolean> {
  if (!viewer) return false;
  const follow = await prisma.follow.findUnique({
    where: {
      followerId_followingId: {
        followerId: viewer.id,
        followingId: target.id,
      },
    },
  });
  return follow !== null;
}

/** 프로필 조회 및 팔로우 관련 라우트 */
export async function profileRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: { username: string } }>(
    "/api/profiles/:username",
    async (request, reply) => {
      const viewer = await optionalUser(request);
      const target = await findProfileOr404(request.params.username);
      return reply.send({
        profile: toProfileView(target, await isFollowing(viewer, target)),
      });
    },
  );

  app.post<{ Params: { username: string } }>(
    "/api/profiles/:username/follow",
    async (request, reply) => {
      const viewer = await requireUser(request);
      const target = await findProfileOr404(request.params.username);

      if (target.id !== viewer.id) {
        // 이미 팔로우 중이면 그대로 둔다 (멱등).
        await prisma.follow.upsert({
          where: {
            followerId_followingId: {
              followerId: viewer.id,
              followingId: target.id,
            },
          },
          create: { followerId: viewer.id, followingId: target.id },
          update: {},
        });
      }
      return reply.send({
        profile: toProfileView(target, await isFollowing(viewer, target)),
      });
    },
  );

  app.delete<{ Params: { username: string } }>(
    "/api/profiles/:username/follow",
    async (request, reply) => {
      const viewer = await requireUser(request);
      const target = await findProfileOr404(request.params.username);

      await prisma.follow.deleteMany({
        where: { followerId: viewer.id, followingId: target.id },
      });
      return reply.send({ profile: toProfileView(target, false) });
    },
  );
}

