      const currentUser = await requireUser(request);
      const article = await findArticleOr404(request.params.slug);

      await prisma.favorite.upsert({
        where: {
          userId_articleId: { userId: currentUser.id, articleId: article.id },
        },
        create: { userId: currentUser.id, articleId: article.id },
        update: {},
      });

      return reply.send({
        article: await toSingleArticleView(article, currentUser),
      });
    },
  );

  // 즐겨찾기 해제
  app.delete<{ Params: { slug: string } }>(
    "/api/articles/:slug/favorite",
    async (request, reply) => {
      const currentUser = await requireUser(request);
      const article = await findArticleOr404(request.params.slug);

