import type { FastifyInstance } from "fastify";
import type { User } from "@prisma/client";
import { optionalUser, requireUser } from "../lib/auth.js";
import { forbidden, notFound } from "../lib/errors.js";
import { toCommentView } from "../lib/presenters.js";
import { prisma } from "../lib/prisma.js";
import { Validator, asRecord, requireString } from "../lib/validation.js";

/** slug로 아티클 id를 찾고, 없으면 404를 던진다. */
async function findArticleIdOr404(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({
    where: { slug },
    select: { id: true },
  });
  if (!article) throw notFound("article");
  return article.id;
}

/** 현재 사용자가 팔로우 중인 작성자 id 집합 */
async function followingSet(
  viewer: User | null,
  authorIds: number[],
): Promise<Set<number>> {
  if (!viewer || authorIds.length === 0) return new Set();
  const follows = await prisma.follow.findMany({
    where: { followerId: viewer.id, followingId: { in: authorIds } },
    select: { followingId: true },
  });
  return new Set(follows.map((f) => f.followingId));
}

/** 코멘트 라우트 */
export async function commentRoutes(app: FastifyInstance): Promise<void> {
  // 코멘트 목록 (인증 선택)
  app.get<{ Params: { slug: string } }>(
    "/api/articles/:slug/comments",
    async (request, reply) => {
      const viewer = await optionalUser(request);
      const articleId = await findArticleIdOr404(request.params.slug);

      const comments = await prisma.comment.findMany({
        where: { articleId },
        include: { author: true },
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      });
      const following = await followingSet(
        viewer,
        comments.map((c) => c.authorId),
      );

      return reply.send({
        comments: comments.map((c) =>
          toCommentView(c, following.has(c.authorId)),
        ),
      });
    },
  );

  // 코멘트 작성
  app.post<{ Params: { slug: string } }>(
    "/api/articles/:slug/comments",
    async (request, reply) => {
      const currentUser = await requireUser(request);
      const articleId = await findArticleIdOr404(request.params.slug);

      const input = asRecord(asRecord(request.body).comment);
      const v = new Validator();
      const body = requireString(v, input, "body");
      v.throwIfInvalid();

      const comment = await prisma.comment.create({
        data: { body: body!, authorId: currentUser.id, articleId },
        include: { author: true },
      });

      return reply.code(201).send({ comment: toCommentView(comment, false) });
    },
  );

  // 코멘트 삭제 (작성자만)
  app.delete<{ Params: { slug: string; id: string } }>(
    "/api/articles/:slug/comments/:id",
    async (request, reply) => {
      const currentUser = await requireUser(request);
      const articleId = await findArticleIdOr404(request.params.slug);

      const commentId = Number.parseInt(request.params.id, 10);
      const comment = Number.isFinite(commentId)
        ? await prisma.comment.findFirst({ where: { id: commentId, articleId } })
        : null;
      if (!comment) throw notFound("comment");
      if (comment.authorId !== currentUser.id) throw forbidden("comment");

      await prisma.comment.delete({ where: { id: comment.id } });
      return reply.code(204).send();
    },
  );
}

