  return app;
}

import Fastify, { type FastifyInstance } from "fastify";
import { Prisma } from "@prisma/client";
import { ApiError } from "./lib/errors.js";
import { articleRoutes } from "./routes/articles.js";
import { commentRoutes } from "./routes/comments.js";
import { profileRoutes } from "./routes/profiles.js";
import { tagRoutes } from "./routes/tags.js";
import { userRoutes } from "./routes/users.js";

/** Fastify 인스턴스를 구성해 돌려준다. */
export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: process.env.LOG_LEVEL !== "silent" && { level: process.env.LOG_LEVEL ?? "warn" },
    // 본문이 비어 있는 POST/DELETE(예: 즐겨찾기)도 허용한다.
    ignoreTrailingSlash: true,
  });

  // 간단한 CORS 처리 — 프런트엔드에서 바로 붙을 수 있게 한다.
  app.addHook("onRequest", async (request, reply) => {
    reply.header("Access-Control-Allow-Origin", "*");
    reply.header(
      "Access-Control-Allow-Methods",
      "GET,POST,PUT,DELETE,OPTIONS",
    );
    reply.header("Access-Control-Allow-Headers", "Content-Type,Authorization");
    if (request.method === "OPTIONS") return reply.code(204).send();
  });

  // 에러 핸들러는 라우트 등록보다 먼저 설정해야 하위 컨텍스트가 이를 상속한다.
  app.setNotFoundHandler(async (_request, reply) =>
    reply.code(404).send({ errors: { route: ["not found"] } }),
  );

  app.setErrorHandler(async (error, _request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.errors });
    }

    // Prisma 유일성 제약 위반은 409로 변환한다.
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      const target = (error.meta?.target as string[] | undefined) ?? [];
      const field = target[0] ?? "record";
      return reply
        .code(409)
        .send({ errors: { [field]: ["has already been taken"] } });
    }

    // 잘못된 JSON 등 요청 형식 오류
    const statusCode = (error as { statusCode?: number }).statusCode ?? 500;
    if (statusCode === 400 || statusCode === 415) {
      return reply.code(422).send({ errors: { body: ["is invalid"] } });
    }

    _request.log.error({ err: error }, "처리되지 않은 오류");
    return reply.code(500).send({ errors: { server: ["internal error"] } });
  });

  await app.register(userRoutes);
  await app.register(profileRoutes);
  await app.register(articleRoutes);
  await app.register(commentRoutes);
  await app.register(tagRoutes);

  return app;
}

